stageCss:
#stage .vs-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .vs-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .vs-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .vs-mark svg{ width:25px; height:25px; }
#stage .vs-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .vs-count{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .vs-count b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .vs-count i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .vs-verdict{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vs-verdict i{
  width:10px; height:10px; border-radius:50%; background:var(--text-dim);
  animation:msd-breathe 2s ease-in-out infinite;
}
#stage .vs-verdict b{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .vs-verdict.sb{ border-color:rgba(58,160,255,.55); background:rgba(58,160,255,.12); }
#stage .vs-verdict.sb i{ background:var(--accent-1); box-shadow:0 0 12px var(--accent-1); }
#stage .vs-verdict.sb b{ color:var(--accent-1); }
#stage .vs-verdict.qs{ border-color:rgba(34,211,238,.55); background:rgba(34,211,238,.12); }
#stage .vs-verdict.qs i{ background:var(--accent-cyan); box-shadow:0 0 12px var(--accent-cyan); }
#stage .vs-verdict.qs b{ color:var(--accent-cyan); }

/* ============================= SCENE STACK ============================= */
#stage .vs-body{ position:relative; flex:1; min-height:0; }
#stage .vs-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .vs-sc.on{ opacity:1; transform:none; }
#stage .vs-sc.whip{ animation:vs-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .vs-board{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------- question -- */
#stage .vs-q{
  height:190px; flex-shrink:0; display:flex; flex-direction:column; justify-content:center; gap:12px;
  padding:18px 24px; border-radius:26px;
  background:radial-gradient(circle at 12% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.7);
  border:2px solid rgba(58,160,255,.45);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .vs-q.hot{ box-shadow:0 0 0 1px rgba(58,160,255,.25), 0 0 60px rgba(58,160,255,.16); }
#stage .vs-qn{
  align-self:flex-start; padding:6px 15px; border-radius:8px;
  background:rgba(58,160,255,.18); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .vs-qt{ color:#fff; font-size:34px; font-weight:800; letter-spacing:-.6px; line-height:1.15; }
#stage .vs-qa{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  transition:color .3s ease;
}
#stage .vs-qa.sb{ color:var(--accent-1); }
#stage .vs-qa.qs{ color:var(--accent-cyan); }

/* ------------------------------------------------------------ the boards -- */
#stage .vs-cols{ flex:1; min-height:0; display:flex; gap:14px; }
#stage .vs-col{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:12px;
  padding:18px 16px; border-radius:26px;
  background:rgba(20,27,43,.6); border:2px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease, filter .3s ease;
}
#stage .vs-col.qs{ border-color:rgba(34,211,238,.4); }
#stage .vs-col.sb{ border-color:rgba(58,160,255,.4); }
#stage .vs-col.lead{ box-shadow:0 0 0 1px rgba(58,160,255,.22), 0 0 60px rgba(58,160,255,.16); }
#stage .vs-col.qs.lead{ box-shadow:0 0 0 1px rgba(34,211,238,.24), 0 0 60px rgba(34,211,238,.16); }
#stage .vs-col.fade{ opacity:.5; filter:saturate(.4); }
#stage .vs-col-h{ display:flex; align-items:center; gap:12px; }
#stage .vs-col-ic{ font-size:30px; flex-shrink:0; }
#stage .vs-col-h b{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .vs-col-v{
  align-self:flex-start; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:700; letter-spacing:1px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .vs-col-v.win{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .vs-col-v.lose{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger); }
#stage .vs-col-list{ display:flex; flex-direction:column; gap:9px; }
#stage .vs-r{
  display:flex; align-items:center; gap:10px;
  padding:11px 12px; border-radius:12px; white-space:nowrap; overflow:hidden;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
}
#stage .vs-r i{ font-style:normal; font-size:16px; flex-shrink:0; }
#stage .vs-r.win{ border-color:rgba(63,185,80,.4); background:rgba(63,185,80,.09); color:#bff0c4; }

#stage .vs-note{
  height:112px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vs-note.hot{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.07); }
#stage .vs-note.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.07); }
#stage .vs-note-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.3);
}
#stage .vs-note-t{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }

#stage .vs-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vs-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .vs-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .vs-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .vs-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .vs-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .vs-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ====================== SCENE 2 · THE WHOLE DECISION =================== */
#stage .vs-flow{
  display:flex; flex-direction:column; justify-content:center; gap:14px; height:100%;
}
#stage .vs-frow{
  height:110px; flex-shrink:0; display:flex; align-items:center; gap:18px;
  padding:0 24px; border-radius:22px;
  background:rgba(20,27,43,.65); border:1.5px solid var(--border);
}
#stage .vs-fq{ color:#fff; font-size:27px; font-weight:700; letter-spacing:-.3px; }
#stage .vs-fa{
  margin-left:auto; flex-shrink:0; padding:12px 22px; border-radius:14px; white-space:nowrap;
  font-family:var(--font-mono); font-size:21px; font-weight:800;
}
#stage .vs-fa.sb{ background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.55); color:var(--accent-1); }
#stage .vs-fa.qs{ background:rgba(34,211,238,.16); border:1.5px solid rgba(34,211,238,.6); color:var(--accent-cyan); }
#stage .vs-rule{
  height:132px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 24px; border-radius:24px;
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.12), transparent 62%), rgba(20,27,43,.7);
  border:2px solid rgba(63,185,80,.45);
}
#stage .vs-rule-a, #stage .vs-rule-b{
  flex:1; text-align:center; padding:16px 10px; border-radius:16px; white-space:nowrap;
  font-size:24px; font-weight:700;
}
#stage .vs-rule-a{ background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--text-primary); }
#stage .vs-rule-a b{ color:var(--accent-1); }
#stage .vs-rule-b{ background:rgba(34,211,238,.12); border:1.5px solid rgba(34,211,238,.5); color:var(--text-primary); }
#stage .vs-rule-b b{ color:var(--accent-cyan); }

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .vs-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .vs-badge{
  width:132px; height:132px; border-radius:36px; font-size:62px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.28), rgba(34,211,238,.16));
  border:2px solid rgba(58,160,255,.6);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 80px rgba(58,160,255,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .vs-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:3px; }
#stage .vs-fin-h{ color:#fff; font-size:58px; font-weight:900; line-height:1.14; letter-spacing:-1.6px; }
#stage .vs-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .vs-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .vs-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .vs-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:850px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .vs-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes vs-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

