var VS = window.__VS || (window.__VS = {});

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.q('#vs-app').textContent = 'picking a queue · 5 questions';
MSD.q('#vs-count-n').textContent = '0';
MSD.cls('#vs-verdict', 'sb', false);
MSD.cls('#vs-verdict', 'qs', false);
MSD.q('#vs-verdict-t').textContent = 'undecided';

MSD.q('#vs-qn').textContent = 'Q0';
MSD.q('#vs-qt').textContent = 'Which queue should you actually use?';
MSD.q('#vs-qa').textContent = "let's find out";
MSD.cls('#vs-qa', 'sb', false);
MSD.cls('#vs-qa', 'qs', false);
MSD.cls('#vs-q', 'hot', false);

MSD.cls('.vs-col', 'lead', false);
MSD.cls('.vs-col', 'fade', false);
MSD.q('#vs-col-qs-v').textContent = 'in the running';
MSD.q('#vs-col-sb-v').textContent = 'in the running';
MSD.cls('.vs-col-v', 'win', false);
MSD.cls('.vs-col-v', 'lose', false);
MSD.hide('.vs-r');
MSD.hide('.vs-frow');
MSD.hide('.vs-fin-p');

MSD.cls('#vs-note', 'hot', false);
MSD.cls('#vs-note', 'bad', false);
MSD.q('#vs-note-ic').textContent = '💡';
MSD.q('#vs-note-t').textContent = 'Both are queues. Only one of them is already sitting in your resource group.';
MSD.cls('#vs-strip', 'bad', false);
MSD.cls('#vs-strip', 'good', false);
MSD.q('#vs-strip-l').textContent = 'START';
MSD.q('#vs-strip-t').textContent = 'You will make this call this week. Make it on a question, not a habit.';

MSD.after(500, function(){ MSD.punch('#vs-col-qs', 1); MSD.sfx.blip(1); });
MSD.after(900, function(){ MSD.punch('#vs-col-sb', 3); MSD.sfx.blip(3); });
MSD.after(1700, function(){ MSD.punch('#vs-q', 4); });

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.hide('.vs-r');
MSD.cls('.vs-col', 'lead', false);
MSD.cls('.vs-col', 'fade', false);
MSD.q('#vs-qn').textContent = 'Q0';
MSD.q('#vs-qt').textContent = 'How did you choose last time?';
MSD.cls('#vs-strip', 'good', false);
MSD.cls('#vs-strip', 'bad', true);
MSD.q('#vs-strip-l').textContent = 'HABIT';
MSD.q('#vs-strip-t').textContent = 'Paying for a broker you use like a to-do list is a real, recurring cost.';

MSD.after(300, function(){
  MSD.q('#vs-qa').textContent = '“it is the enterprise one”';
  MSD.cls('#vs-note', 'bad', true);
  MSD.q('#vs-note-ic').textContent = '🙈';
  MSD.q('#vs-note-t').textContent = '“We always use Service Bus” · “the other one looks too simple”';
  MSD.punch('#vs-note', 2);
  MSD.sfx.error();
});
MSD.after(1300, function(){
  MSD.q('#vs-qa').textContent = 'neither of those is a requirement';
  MSD.shake('#vs-note');
  MSD.sfx.error();
});
MSD.after(2100, function(){
  MSD.q('#vs-qt').textContent = 'Five questions settle it properly';
  MSD.cls('#vs-q', 'hot', true);
  MSD.punch('#vs-q', 5);
  MSD.sfx.lock();
});

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.cls('#vs-note', 'bad', false);
MSD.cls('#vs-q', 'hot', true);
MSD.q('#vs-qn').textContent = 'Q1';
MSD.q('#vs-qt').textContent = 'Does more than one consumer need it?';
MSD.q('#vs-qa').textContent = 'thinking…';
MSD.cls('#vs-qa', 'qs', false);
MSD.cls('#vs-qa', 'sb', false);
MSD.q('#vs-count-n').textContent = '1';
MSD.cls('#vs-strip', 'bad', false);
MSD.q('#vs-strip-l').textContent = 'FAN-OUT';
MSD.q('#vs-strip-t').textContent = 'Two teams wanting the same message is the most common reason to need a topic.';

MSD.after(400, function(){ MSD.show('#vs-qs-1', 0); });
MSD.after(800, function(){
  MSD.show('#vs-sb-1', 0);
  MSD.cls('#vs-qa', 'sb', true);
  MSD.q('#vs-qa').textContent = 'yes → Service Bus topics';
  MSD.cls('#vs-verdict', 'qs', false);
  MSD.cls('#vs-verdict', 'sb', true);
  MSD.q('#vs-verdict-t').textContent = 'Service Bus';
  MSD.cls('#vs-col-sb', 'lead', true);
  MSD.punch('#vs-col-sb', 3);
  MSD.sfx.blip(3);
});
MSD.after(1900, function(){
  MSD.q('#vs-note-ic').textContent = '📢';
  MSD.q('#vs-note-t').textContent = 'A Queue Storage message is consumed once. There is no second reader, ever.';
  MSD.punch('#vs-note', 4);
});

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.cls('#vs-note', 'bad', false);
MSD.cls('#vs-q', 'hot', true);
MSD.cls('#vs-col-sb', 'lead', true);
MSD.show('.vs-r.q1', 0, true);
MSD.q('#vs-qn').textContent = 'Q2';
MSD.q('#vs-qt').textContent = 'Does the order have to hold?';
MSD.q('#vs-qa').textContent = 'thinking…';
MSD.cls('#vs-qa', 'qs', false);
MSD.cls('#vs-qa', 'sb', false);
MSD.q('#vs-count-n').textContent = '2';
MSD.q('#vs-strip-l').textContent = 'FIFO';
MSD.q('#vs-strip-t').textContent = '“Cancel” arriving before “create” is the bug this question prevents.';

MSD.after(400, function(){ MSD.show('#vs-qs-2', 0); });
MSD.after(900, function(){
  MSD.show('#vs-sb-2', 0);
  MSD.cls('#vs-qa', 'sb', true);
  MSD.q('#vs-qa').textContent = 'yes → sessions, one consumer per session';
  MSD.punch('#vs-col-sb', 3);
  MSD.sfx.blip(3);
});
MSD.after(1800, function(){
  MSD.q('#vs-note-ic').textContent = '🔢';
  MSD.q('#vs-note-t').textContent = 'Best-effort means usually in order. Usually is not a guarantee you can design on.';
  MSD.punch('#vs-note', 4);
});

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.cls('#vs-note', 'bad', false);
MSD.cls('#vs-q', 'hot', true);
MSD.cls('#vs-col-sb', 'lead', true);
MSD.show('.vs-r.q1', 0, true);
MSD.show('.vs-r.q2', 0, true);
MSD.q('#vs-qn').textContent = 'Q3';
MSD.q('#vs-qt').textContent = 'Is the payload over 64 KB?';
MSD.q('#vs-qa').textContent = 'thinking…';
MSD.cls('#vs-qa', 'qs', false);
MSD.cls('#vs-qa', 'sb', false);
MSD.q('#vs-count-n').textContent = '3';
MSD.q('#vs-strip-l').textContent = 'SIZE';
MSD.q('#vs-strip-t').textContent = 'Most messages are a few hundred bytes. This one matters less than people think.';

MSD.after(400, function(){ MSD.show('#vs-qs-3', 0); });
MSD.after(900, function(){
  MSD.show('#vs-sb-3', 0);
  MSD.cls('#vs-qa', 'sb', true);
  MSD.q('#vs-qa').textContent = 'yes → Service Bus';
  MSD.punch('#vs-col-sb', 3);
  MSD.sfx.blip(3);
});
MSD.after(1800, function(){
  MSD.q('#vs-note-ic').textContent = '🔗';
  MSD.q('#vs-note-t').textContent = 'Or put the payload in a blob and send the pointer — then 64 KB is plenty.';
  MSD.cls('#vs-qa', 'sb', false);
  MSD.cls('#vs-qa', 'qs', true);
  MSD.q('#vs-qa').textContent = 'claim check → Queue Storage is fine';
  MSD.punch('#vs-col-qs', 4);
  MSD.sfx.pop();
});

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.cls('#vs-note', 'bad', false);
MSD.cls('#vs-q', 'hot', true);
MSD.cls('#vs-col-sb', 'lead', true);
MSD.show('.vs-r.q1', 0, true);
MSD.show('.vs-r.q2', 0, true);
MSD.show('.vs-r.q3', 0, true);
MSD.q('#vs-qn').textContent = 'Q4';
MSD.q('#vs-qt').textContent = 'Do you need DLQ, dedupe or transactions?';
MSD.q('#vs-qa').textContent = 'thinking…';
MSD.cls('#vs-qa', 'qs', false);
MSD.cls('#vs-qa', 'sb', false);
MSD.q('#vs-count-n').textContent = '4';
MSD.q('#vs-strip-l').textContent = 'SAFETY';
MSD.q('#vs-strip-t').textContent = 'Sending two messages atomically is a Service Bus feature you cannot fake cheaply.';

MSD.after(400, function(){ MSD.show('#vs-qs-4', 0); });
MSD.after(900, function(){
  MSD.show('#vs-sb-4', 0);
  MSD.cls('#vs-qa', 'sb', true);
  MSD.q('#vs-qa').textContent = 'yes → Service Bus, comfortably';
  MSD.punch('#vs-col-sb', 4);
  MSD.sfx.blip(4);
});
MSD.after(1800, function(){
  MSD.q('#vs-note-ic').textContent = '☠️';
  MSD.q('#vs-note-t').textContent = 'The Functions queue trigger will move poison messages for you — nothing else will.';
  MSD.punch('#vs-note', 5);
});

var VS = window.__VS;

MSD.cls('.vs-sc', 'on', false);
MSD.cls('#vs-sc-board', 'on', true);
MSD.cls('#vs-note', 'bad', false);
MSD.cls('#vs-q', 'hot', true);
MSD.show('.vs-r.q1', 0, true);
MSD.show('.vs-r.q2', 0, true);
MSD.show('.vs-r.q3', 0, true);
MSD.show('.vs-r.q4', 0, true);
MSD.q('#vs-qn').textContent = 'Q5';
MSD.q('#vs-qt').textContent = 'How much backlog must it survive?';
MSD.q('#vs-qa').textContent = 'thinking…';
MSD.cls('#vs-qa', 'sb', false);
